-- Sementa: content + mission DATA migration
-- Run AFTER docs/DB-SETUP.sql (structure) on the target project.
-- Contains NO user data (no profiles, roles, xp, progress, friendships).
-- Idempotent: every insert uses ON CONFLICT DO NOTHING and preserves original ids.
-- NOTE: image urls (avatars, welcome_cards, classes.hero_image_url) still point at the
-- source project's public storage. Copy the files into the clone's buckets and update
-- the urls if you need full independence.

begin;
set local session_replication_role = 'replica';


-- pillars (4 rows)
on conflict (id) do nothing;

-- topics (20 rows)
on conflict (id) do nothing;

-- modules (100 rows)
on conflict (id) do nothing;

-- classes (40 rows)
on conflict (id) do nothing;

-- layers (173 rows)
on conflict (id) do nothing;

-- mission_crosswords (1 rows)
on conflict (id) do nothing;

-- mission_crossword_variants (3 rows)
on conflict (id) do nothing;

-- mission_crossword_words (13 rows)
on conflict (id) do nothing;

-- mission_quizzes (2 rows)
on conflict (id) do nothing;

-- mission_quiz_questions (20 rows)
on conflict (id) do nothing;

-- mission_quiz_choices (80 rows)
on conflict (id) do nothing;

-- avatars (8 rows)
on conflict (id) do nothing;

-- welcome_cards (4 rows)
on conflict (id) do nothing;

commit;
