  ('371231dd-8169-48db-bf2a-212e20eeef5d'::uuid, '1806ac86-0ae6-413a-b57e-34c6c744c410'::uuid, 1, 'foundation'::layer_type, 'Maya Finds a Wallet', '{"prompt": "Maya finds a small wallet at the park. Nobody is around. Inside is some money and a note with an address. What does she do?", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('a49fc733-3433-49a0-8bde-b6dace17b6bf'::uuid, '1806ac86-0ae6-413a-b57e-34c6c744c410'::uuid, 2, 'simulation'::layer_type, 'What Should Maya Do?', '{"prompt": "Story pauses. Options: (A) Keep it — nobody will ever know. (B) Leave it — not her problem. (C) Try to return it — even though it''s hard. Three paths play out.", "taskCode": "T07"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('84917727-22c4-4ad6-9aad-026cb7be1d15'::uuid, '1806ac86-0ae6-413a-b57e-34c6c744c410'::uuid, 3, 'reflection'::layer_type, 'Your Honest Moment', E'{"prompt": "Record: \\"Tell me about a time you did something right even though nobody was watching. How did it feel?\\"", "taskCode": "T10"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
