  ('596e5c01-c940-41a1-9d28-78b35872e142'::uuid, '1faae0be-7b32-4eef-95e4-1e7b23deffa9'::uuid, 4, 'reflection'::layer_type, 'Your Turn', E'{"prompt": "Pip asks: \\"Has a feeling ever gotten stuck inside you? What did it feel like?\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:41:22.399387+00'::timestamptz, '2026-05-07 07:41:22.399387+00'::timestamptz),
  ('e6492206-77f0-4027-a982-42e02d6a4269'::uuid, '26e19f4a-0939-4bf8-8b9a-e50cea83ff08'::uuid, 1, 'foundation'::layer_type, 'Pip enters the Fear House', '{"taskCode": "T01", "videoUrl": "https://cdn.sementa.app/v/c04-fear-house.mp4", "transcript": "Pip is too scared to enter the Fear House alone. Maya holds her paw and goes in with her. Inside they discover that fear is actually trying to protect you — it is your body saying be careful.", "durationSec": 85, "skipAllowed": false, "characterFocus": ["Pip"]}'::jsonb, 5, '2026-05-06 12:19:21.233709+00'::timestamptz, '2026-05-06 12:19:21.233709+00'::timestamptz),
