  ('f1882bff-c174-4242-b415-af5d3dc14985'::uuid, '3b0b53b7-68a6-42d5-af52-bdf3ce78933b'::uuid, 4, 'reflection'::layer_type, 'Body Talk', E'{"prompt": "\\"What does YOUR body do when you''re excited? Nervous? Draw it or tell Pip.\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('b1ea4dc7-201b-4390-b806-21cddccb0529'::uuid, '48c5865c-036f-4bba-a6c9-a9dca328d186'::uuid, 1, 'foundation'::layer_type, 'Dash erupts at the Anger Volcano', '{"taskCode": "T01", "videoUrl": "https://cdn.sementa.app/v/c05-anger-volcano.mp4", "transcript": "Dash loses the game and ERUPTS — he knocks over the stall and storms off. Leo follows him. Together they discover that anger is not bad — it is what you DO with anger that matters.", "durationSec": 90, "skipAllowed": false, "characterFocus": ["Dash"]}'::jsonb, 5, '2026-05-05 12:10:18.047931+00'::timestamptz, '2026-05-05 12:10:18.047931+00'::timestamptz),
  ('595af786-66e3-479e-9fa1-cb975c53ded0'::uuid, '48c5865c-036f-4bba-a6c9-a9dca328d186'::uuid, 2, 'foundation'::layer_type, 'The 5-second pause trick', '{"caption": "Before you react… 1… 2… 3… 4… 5. NOW decide.", "taskCode": "T02", "videoUrl": "https://cdn.sementa.app/v/c05-pause-trick.mp4", "durationSec": 25, "characterFocus": ["Dash"]}'::jsonb, 3, '2026-05-05 12:10:18.047931+00'::timestamptz, '2026-05-05 12:10:18.047931+00'::timestamptz),
  ('fbe9a0e9-1e37-4520-a874-acfe91445d21'::uuid, '48c5865c-036f-4bba-a6c9-a9dca328d186'::uuid, 3, 'quiz'::layer_type, 'True or False — what helps anger cool down?', '{"shuffle": true, "taskCode": "T04", "questions": [{"prompt": "Taking 5 deep breaths can help anger shrink.", "correct": "True", "options": ["True", "False"]}, {"prompt": "Hitting something makes the anger go away for good.", "correct": "False", "options": ["True", "False"]}, {"prompt": "Telling someone why you are angry can help.", "correct": "True", "options": ["True", "False"]}, {"prompt": "Screaming at your friend makes things better.", "correct": "False", "options": ["True", "False"]}, {"prompt": "Moving your body can help release anger energy.", "correct": "True", "options": ["True", "False"]}], "timeLimitSec": 5, "speedBonusSec": 2}'::jsonb, 10, '2026-05-05 12:10:18.047931+00'::timestamptz, '2026-05-05 12:10:18.047931+00'::timestamptz),
  ('fe9ad162-2b30-40bb-a469-e50aab52ab4e'::uuid, '48c5865c-036f-4bba-a6c9-a9dca328d186'::uuid, 4, 'simulation'::layer_type, 'Dash is about to lose it — what does he do?', '{"options": [{"label": "Shout at Leo and walk away", "isOptimal": false, "outcomeText": "Leo feels hurt. Dash still feels angry AND now feels guilty too."}, {"label": "Count to 5 and take a big breath", "isOptimal": true, "outcomeText": "The volcano cools. Dash can now talk about what happened."}, {"label": "Pretend nothing happened and keep playing", "isOptimal": false, "outcomeText": "The anger stays inside like a lid on a boiling pot. It comes out later."}], "taskCode": "T07", "setupClipUrl": "https://cdn.sementa.app/v/c05-dash-angry.mp4", "showAllPaths": true, "decisionPrompt": "Dash feels the volcano rising. What should he do RIGHT NOW?"}'::jsonb, 15, '2026-05-05 12:10:18.047931+00'::timestamptz, '2026-05-05 12:10:18.047931+00'::timestamptz),
  ('693f7770-0b4f-4389-a0c5-2ad7c2bb147d'::uuid, '48c5865c-036f-4bba-a6c9-a9dca328d186'::uuid, 5, 'reflection'::layer_type, 'Try the pause before you react', '{"title": "The Pause Challenge", "taskCode": "T13", "windowDays": 7, "instruction": "This week, when you feel angry, try the 5-second pause before you do anything. Then tell a grown-up how it went.", "missionType": "Practice", "parentNotice": "Your child is practising the 5-second pause this week — help them notice moments to use it!", "verifyForBonus": true}'::jsonb, 25, '2026-05-05 12:10:18.047931+00'::timestamptz, '2026-05-05 12:10:18.047931+00'::timestamptz),
