  ('ece2acc4-fac9-4f07-8f54-709626e8ea79'::uuid, '958e214e-163d-413d-8010-f115f7507664'::uuid, 1, 'foundation'::layer_type, 'The Feeling Mountain', '{"prompt": "Leo''s feelings pile up like boulders. Pip names each one — happy, sad, scared, angry, surprised, disgusted — and the mountain shrinks.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('900a3628-ac93-4a74-b7d2-288b709df071'::uuid, '958e214e-163d-413d-8010-f115f7507664'::uuid, 2, 'quiz'::layer_type, 'Sort the Feelings', '{"prompt": "Six emotion faces appear. Child drags each one into Leo''s body — where does he feel it? Chest, tummy, head, hands.", "taskCode": "T03"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('fe1b46c8-8404-46e7-ae48-f886fb6a212d'::uuid, '958e214e-163d-413d-8010-f115f7507664'::uuid, 3, 'quiz'::layer_type, 'Feelings Quiz', E'{"prompt": "Q1: How many core feelings did Pip name? Q2: Where did Leo feel \\"scared\\" in his body? Q3: What feeling shrinks when you name it?", "taskCode": "T05"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('2f43ba64-0722-4d04-a834-3d3597afc82d'::uuid, '958e214e-163d-413d-8010-f115f7507664'::uuid, 4, 'reflection'::layer_type, 'Feeling Finder Mission', '{"prompt": "Tonight before bed, tell someone in your house ONE feeling you had today and WHERE you felt it in your body.", "taskCode": "T13"}'::jsonb, 25, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('9148b068-dcea-4d19-aed9-e1454e23ef9b'::uuid, '96180f6f-3b99-41b5-a220-e6a5e5d9ffff'::uuid, 1, 'foundation'::layer_type, 'The Lonely Lunch Table', '{"prompt": "Maya and Leo pass a child sitting alone. Maya nearly keeps walking. Leo stops. The story follows both choices — and shows what one moment of kindness does to a whole day.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
