  ('8e91b6bb-e99b-4272-9bc0-c68513823b92'::uuid, '96180f6f-3b99-41b5-a220-e6a5e5d9ffff'::uuid, 4, 'reflection'::layer_type, 'Your Kindness Moment', E'{"prompt": "\\"Is there someone near you who might be lonely or left out? What''s one small thing you could do? Tell Pip — just between you two.\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('8d276cc5-6327-474a-8b13-6fa67a4c81b7'::uuid, 'ad68fc23-1bbb-4f7b-a689-fb783cf96c76'::uuid, 1, 'foundation'::layer_type, 'Leo''s Moment', '{"prompt": "Dash is about to say something mean about Pip to get a laugh from others. Leo is right there. Speaking up means risking being laughed at too.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
