  ('66bd9a64-745a-44d1-b136-d4298b2a822e'::uuid, 'b408152f-4f12-4635-98be-a61999304add'::uuid, 1, 'foundation'::layer_type, 'Maya''s Hard Day', '{"prompt": "Maya can tell her friend she can''t come to her party (friend will be sad) OR go but miss her family dinner (family will be disappointed). Both feel awful. What does she do?", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('af3efd2c-e213-45f4-b047-2483af72e192'::uuid, 'b408152f-4f12-4635-98be-a61999304add'::uuid, 2, 'simulation'::layer_type, 'Help Maya Choose', '{"prompt": "Three paths: (A) Do nothing — avoid deciding. (B) Make a choice and explain it kindly. (C) Ask a grown-up to help decide. All three play out.", "taskCode": "T07"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
