  ('c83fd579-91d5-4a09-a958-c1dcacd01716'::uuid, 'b408152f-4f12-4635-98be-a61999304add'::uuid, 4, 'reflection'::layer_type, 'Hard Choices', E'{"prompt": "\\"What makes a choice hard? Tell Pip the one thing that makes deciding difficult for you.\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('87957b03-a8e1-4a92-9820-049b407b0284'::uuid, 'b6721c75-0dc0-4a87-8b64-085c9fc99ee8'::uuid, 1, 'foundation'::layer_type, 'Maya''s Big Voice', '{"prompt": "Maya gets frustrated and shouts at Leo. He looks hurt. The story pauses — what could Maya have said instead?", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('c254d7c5-8d34-44fc-a804-5ae03371e333'::uuid, 'b6721c75-0dc0-4a87-8b64-085c9fc99ee8'::uuid, 2, 'simulation'::layer_type, 'What Should Maya Do?', E'{"prompt": "Story pauses. Options: (A) Shout louder. (B) Walk away and say nothing. (C) Take a breath and say \\"I feel frustrated when…\\". Each path plays out.", "taskCode": "T07"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('aede5912-a20d-4acd-92fd-82aa3f3b4b36'::uuid, 'b6721c75-0dc0-4a87-8b64-085c9fc99ee8'::uuid, 3, 'reflection'::layer_type, 'Calm Words', E'{"prompt": "\\"Think of a time you felt like shouting. What calmer words could you have used instead? Tell Pip.\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('d1ece3e3-e68b-4c2e-bfa1-7e04fe8681db'::uuid, 'bd6b0396-4d7a-4ba8-af7f-7396f72dfba9'::uuid, 1, 'foundation'::layer_type, 'The Leader Debate', '{"prompt": "Maya says a leader is the strongest. Leo says a leader is the kindest. Dash says it''s whoever runs fastest. Pip has no idea. Nobody agrees — which kicks off the whole module.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:42:20.882141+00'::timestamptz, '2026-05-07 07:42:20.882141+00'::timestamptz),
  ('5e929864-f100-4d3d-a122-842fbb289ac0'::uuid, 'bd6b0396-4d7a-4ba8-af7f-7396f72dfba9'::uuid, 2, 'quiz'::layer_type, 'Leader or Not a Leader?', E'{"prompt": "Eight illustrated scenarios. Child matches each to: Real Leader or Just Looks Like One. Example: \\"Takes credit for the group''s work\\" vs \\"Stays late to help someone finish.\\"", "taskCode": "T03"}'::jsonb, 10, '2026-05-07 07:42:20.882141+00'::timestamptz, '2026-05-07 07:42:20.882141+00'::timestamptz),
  ('8d296a0d-291f-4611-aac3-013acb262dd0'::uuid, 'bd6b0396-4d7a-4ba8-af7f-7396f72dfba9'::uuid, 3, 'quiz'::layer_type, 'Leader Check', '{"prompt": "Q1: What does Maya think makes a leader? Q2: What does Leo think? Q3: What do YOU think is the most important thing a leader does?", "taskCode": "T05"}'::jsonb, 10, '2026-05-07 07:42:20.882141+00'::timestamptz, '2026-05-07 07:42:20.882141+00'::timestamptz),
  ('7a43311c-8555-4382-9433-f344d21ce2d3'::uuid, 'bd6b0396-4d7a-4ba8-af7f-7396f72dfba9'::uuid, 4, 'reflection'::layer_type, 'My Leader', E'{"prompt": "\\"Think of someone you think is a good leader. What do they DO that makes you think that? Tell Pip.\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:42:20.882141+00'::timestamptz, '2026-05-07 07:42:20.882141+00'::timestamptz),
  ('7087dd5b-e863-4253-9db3-fcb7e8464307'::uuid, 'be746fba-a691-408a-acd7-0439afee5852'::uuid, 1, 'foundation'::layer_type, 'Everyone feels TWO things at once', '{"taskCode": "T01", "videoUrl": "https://cdn.sementa.app/v/c09-feelings-mix.mp4", "transcript": "It is the last day of the Emotion Fair. Everyone is excited it was so fun — AND sad that it is ending. Dash is proud he won a race AND embarrassed he cried earlier. They discover you can feel two things at exactly the same time, and BOTH feelings are real.", "durationSec": 85, "skipAllowed": false, "characterFocus": ["Maya", "Leo", "Dash", "Pip"]}'::jsonb, 5, '2026-05-05 12:11:48.748069+00'::timestamptz, '2026-05-05 12:11:48.748069+00'::timestamptz),
