  ('8d08db5f-a0d2-42f6-81c3-1409414cd617'::uuid, 'be746fba-a691-408a-acd7-0439afee5852'::uuid, 3, 'quiz'::layer_type, 'One event — two feelings. Can both be true?', '{"cards": [{"answer": "Excited AND Nervous — both true", "situation": "Starting at a new school"}, {"answer": "Sad AND Happy for them — both true", "situation": "Your best friend moves away"}, {"answer": "Proud AND Guilty — both true", "situation": "Winning but your friend loses"}, {"answer": "Sad AND Ready — both true", "situation": "The holidays ending"}], "shuffle": true, "taskCode": "T05"}'::jsonb, 10, '2026-05-05 12:11:48.748069+00'::timestamptz, '2026-05-05 12:11:48.748069+00'::timestamptz),
