  ('14420937-14a1-4b47-ac34-6fdbe25e4178'::uuid, 'dde92454-523d-4d94-a03f-d3cc64860ebd'::uuid, 1, 'foundation'::layer_type, 'Leo''s Big Moment', '{"prompt": "Leo must speak up in front of Maya, Dash, and Pip to save the day. He''s terrified — but he remembers everything he''s learned.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('8f6c86df-0253-4444-91fd-8b7d1b3a99c2'::uuid, 'dde92454-523d-4d94-a03f-d3cc64860ebd'::uuid, 2, 'simulation'::layer_type, 'Help Leo Choose', '{"prompt": "Three moments in the story where Leo can speak up or stay silent. Child guides all three. All paths play out — courage always leads somewhere good.", "taskCode": "T07"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
