  ('53f25c28-62cf-4fac-b2db-90ea2f00fc52'::uuid, 'dde92454-523d-4d94-a03f-d3cc64860ebd'::uuid, 5, 'reflection'::layer_type, 'Module Reflection', E'{"prompt": "\\"What is the most important thing you learned about using your words? If you could tell Leo one thing, what would it be?\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('38780111-74e7-49d6-bad8-049a3a1535a0'::uuid, 'e1bf4dde-b2f2-4c88-ac81-c7c8e1d922b9'::uuid, 1, 'foundation'::layer_type, 'Pip gets stuck on the Worry Spinner', '{"taskCode": "T01", "videoUrl": "https://cdn.sementa.app/v/c07-worry-spinner.mp4", "transcript": "Pip cannot get off the Worry Spinner — her thoughts keep going round and round. What if it rains? What if she gets lost? What if nobody likes her drawing? Maya takes her hand and teaches her the Worry Jar trick: catch the worry, look at it, then decide if it needs action — or can be let go.", "durationSec": 85, "skipAllowed": false, "characterFocus": ["Pip", "Maya"]}'::jsonb, 5, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('6e3b435a-94c2-49e4-9509-251e43d04e73'::uuid, 'e1bf4dde-b2f2-4c88-ac81-c7c8e1d922b9'::uuid, 2, 'simulation'::layer_type, 'Pip''s worry jar breathing journey', '{"guide": "Pip", "script": "Imagine your worry as a little cloud. Breathe it in… now put it gently in the jar… screw on the lid. It is safe in there. You are safe out here. Breathe out slowly.", "audioUrl": "https://cdn.sementa.app/audio/c07-worry-jar.mp3", "taskCode": "T09", "visualUrl": "https://cdn.sementa.app/v/c07-worry-visual.mp4", "durationSec": 90}'::jsonb, 12, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('55ee0e81-8bd5-4893-941d-fee6b3624067'::uuid, 'e1bf4dde-b2f2-4c88-ac81-c7c8e1d922b9'::uuid, 3, 'quiz'::layer_type, 'Things I can control vs. things I cannot', '{"items": [{"label": "Whether it rains tomorrow", "bucket": "Cannot Control"}, {"label": "How I react when something goes wrong", "bucket": "Can Control"}, {"label": "What other people think of me", "bucket": "Cannot Control"}, {"label": "Whether I try my best", "bucket": "Can Control"}, {"label": "If my friend is in a bad mood", "bucket": "Cannot Control"}, {"label": "How kind I am today", "bucket": "Can Control"}], "buckets": [{"label": "Can Control", "colour": "#2E7D32"}, {"label": "Cannot Control", "colour": "#888888"}], "shuffle": true, "taskCode": "T03", "hintAfter": 2, "partialCredit": true}'::jsonb, 10, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('f1d257ad-836e-4fcd-9285-d11ee18defa9'::uuid, 'e1bf4dde-b2f2-4c88-ac81-c7c8e1d922b9'::uuid, 4, 'reflection'::layer_type, 'Tell Pip one worry you have right now', '{"maxSec": 60, "prompt": "Record a message to Pip. Tell her one worry you have and what you are going to do with it.", "taskCode": "T10", "parentLabel": "My Worry Jar", "characterResponse": "Pip"}'::jsonb, 15, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('bf1e11ca-5189-41cc-a170-b6b578237986'::uuid, 'e1bf4dde-b2f2-4c88-ac81-c7c8e1d922b9'::uuid, 5, 'reflection'::layer_type, 'What do you do when you feel worried?', '{"prompt": "What do you usually worry about? What do you do that helps the worry feel smaller?", "taskCode": "T14", "inputType": "Both", "journalLabel": "My Worry Toolkit"}'::jsonb, 10, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('8499d208-e6a0-490a-adbc-0d452c3063a3'::uuid, 'e8456535-8458-486c-a2d4-e868a9e71178'::uuid, 1, 'foundation'::layer_type, 'Not All Choices Are the Same', '{"prompt": "Maya lists her choices for the day: what to wear, what to eat, who to invite to her project, whether to tell the truth about a mistake. Leo helps her see which ones need more thinking.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('db4104d7-7176-4e2c-a57a-b9d43f8f1f82'::uuid, 'e8456535-8458-486c-a2d4-e868a9e71178'::uuid, 2, 'quiz'::layer_type, 'Choice Size Sort', '{"prompt": "Eight choice cards appear (mix of big and small). Child matches each to: Small (just decide quickly) or Big (stop and think). Illustrated.", "taskCode": "T03"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('f18f2af5-484f-439f-853b-f3af29968745'::uuid, 'e8456535-8458-486c-a2d4-e868a9e71178'::uuid, 3, 'reflection'::layer_type, 'Order the Thinking Steps', '{"prompt": "For a BIG choice, drag steps into order: (1) Stop and breathe → (2) What do I want? → (3) Who else is affected? → (4) What are my options? → (5) Choose and go.", "taskCode": "T12"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('86c44d64-6d4f-44d2-9712-887e84e0b2fe'::uuid, 'f30e7c48-c323-4df2-94bf-d204c659b5f5'::uuid, 1, 'foundation'::layer_type, 'Maya Doesn''t Listen', '{"prompt": "Maya is so excited to share her idea that she talks over Leo the whole time. Leo''s face falls. The story explores what real listening looks like.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('e1f0ff39-b33f-402e-a71e-eb6cef94d89f'::uuid, 'f30e7c48-c323-4df2-94bf-d204c659b5f5'::uuid, 2, 'quiz'::layer_type, 'Good Listener Tap-Along', '{"prompt": "Four panels of Leo and Maya talking. Child taps the panel where Maya is being a GOOD listener. Wrong taps show a gentle consequence.", "taskCode": "T05"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('6ce5be8e-522c-45af-8af5-bb1e2f338698'::uuid, 'f30e7c48-c323-4df2-94bf-d204c659b5f5'::uuid, 3, 'reflection'::layer_type, 'Build the Listening Steps', '{"prompt": "Drag-and-drop: put the 4 listening steps in order — Stop talking → Look at the person → Wait for a pause → Respond with what you heard.", "taskCode": "T12"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('f378527c-bc50-49f8-954a-1bb7c7a1285a'::uuid, 'f30e7c48-c323-4df2-94bf-d204c659b5f5'::uuid, 4, 'reflection'::layer_type, 'Who Listened to You?', E'{"prompt": "\\"Think of a time someone really listened to you. How did it make you feel? Tell Pip.\\"", "taskCode": "T14"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('08da21eb-7a4e-41ea-a762-94a24f3f69b6'::uuid, 'f3c41b2b-a25b-492b-b8e3-c0812ef437d8'::uuid, 1, 'foundation'::layer_type, 'Leo Learns a Magic Sentence', E'{"prompt": "Maya teaches Leo: \\"I feel [feeling] when [thing happens].\\" Leo practises it three times in the story.", "taskCode": "T01"}'::jsonb, 5, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('a70bb53c-f392-437d-a706-ec63b8cf04c5'::uuid, 'f3c41b2b-a25b-492b-b8e3-c0812ef437d8'::uuid, 2, 'quiz'::layer_type, 'Finish Leo''s Sentence', E'{"prompt": "Tap-along panels: Leo''s speech bubble is blank. Child taps the right feeling word to complete each \\"I feel…\\" sentence. Three panels.", "taskCode": "T05"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('824a8c25-7ffb-4a69-bd27-baebadba2051'::uuid, 'f3c41b2b-a25b-492b-b8e3-c0812ef437d8'::uuid, 3, 'quiz'::layer_type, 'Formula Check', E'{"prompt": "Q1: What are the two parts of the I Feel sentence? Q2: Leo says \\"I feel __ when you take my things.\\" What word fits the blank? Q3: Why is \\"I feel\\" safer than \\"You always\\"?", "taskCode": "T05"}'::jsonb, 10, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('e41327de-a48d-478f-a0c4-0217c68310a7'::uuid, 'f3c41b2b-a25b-492b-b8e3-c0812ef437d8'::uuid, 4, 'reflection'::layer_type, 'Record Your I Feel', '{"prompt": "Record a voice message using the I Feel formula about something that happened at school or home today.", "taskCode": "T10"}'::jsonb, 15, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('0677bc38-1870-4488-857c-392bec4f66f0'::uuid, 'f3c41b2b-a25b-492b-b8e3-c0812ef437d8'::uuid, 5, 'reflection'::layer_type, 'I Feel in Real Life', '{"prompt": "Today, use the I Feel sentence once with a real person — a family member, a friend, or your teacher.", "taskCode": "T13"}'::jsonb, 25, '2026-05-07 07:14:34.637709+00'::timestamptz, '2026-05-07 07:14:34.637709+00'::timestamptz),
  ('261055f4-228f-4d03-938d-a7cf0d9b4c04'::uuid, 'f912940f-a1db-4f73-af0b-dcffb90c6690'::uuid, 1, 'foundation'::layer_type, 'Maya leads the Proud Parade', '{"taskCode": "T01", "videoUrl": "https://cdn.sementa.app/v/c08-proud-parade.mp4", "transcript": "Maya finally finishes her tower — the one that kept falling down. She feels something warm and tall in her chest. That is pride. But when she starts telling EVERYONE how amazing she is, her friends start looking away. Leo helps her see the difference between proud and boastful.", "durationSec": 80, "skipAllowed": false, "characterFocus": ["Maya"]}'::jsonb, 5, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('608cce37-9a3e-424e-99e4-35f5442b1b74'::uuid, 'f912940f-a1db-4f73-af0b-dcffb90c6690'::uuid, 2, 'quiz'::layer_type, 'Proud or boastful?', '{"shuffle": true, "taskCode": "T04", "questions": [{"prompt": "Sharing your work with a smile.", "correct": "Proud", "options": ["Proud", "Boastful"]}, {"prompt": "Telling everyone yours is the best.", "correct": "Boastful", "options": ["Proud", "Boastful"]}, {"prompt": "Feeling good inside about what you did.", "correct": "Proud", "options": ["Proud", "Boastful"]}, {"prompt": "Saying others are not as good as you.", "correct": "Boastful", "options": ["Proud", "Boastful"]}, {"prompt": "Saying thank you when someone says well done.", "correct": "Proud", "options": ["Proud", "Boastful"]}], "timeLimitSec": 5}'::jsonb, 10, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('1341add6-6bbb-48ee-ab36-de7b44606510'::uuid, 'f912940f-a1db-4f73-af0b-dcffb90c6690'::uuid, 3, 'simulation'::layer_type, 'Maya finishes her drawing — how does she share it?', '{"options": [{"label": "Show it to Leo and say I worked really hard on this", "isOptimal": true, "outcomeText": "Leo smiles and says it is brilliant. Maya feels warm and connected."}, {"label": "Hold it up and announce it is the best drawing ever", "isOptimal": false, "outcomeText": "Some friends roll their eyes. Maya feels proud but alone."}, {"label": "Hide it because she is worried people will not like it", "isOptimal": false, "outcomeText": "Maya misses the chance to feel proud. Her effort goes unseen."}], "taskCode": "T07", "setupClipUrl": "https://cdn.sementa.app/v/c08-maya-drawing.mp4", "showAllPaths": true, "decisionPrompt": "Maya is so proud of her drawing. What should she do?"}'::jsonb, 15, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('e6f48c69-8693-439d-af19-17e2cd5a8d24'::uuid, 'f912940f-a1db-4f73-af0b-dcffb90c6690'::uuid, 4, 'reflection'::layer_type, 'Draw something you are proud of', '{"prompt": "Draw something you worked hard on and feel proud of.", "taskCode": "T11", "voiceLayer": true, "parentLabel": "My Proud Moment"}'::jsonb, 12, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('791b6b22-4d5f-49a8-92f2-a5688e70c7bc'::uuid, 'f912940f-a1db-4f73-af0b-dcffb90c6690'::uuid, 5, 'reflection'::layer_type, 'Tell one person something you are proud of today', '{"title": "Proud Share Mission", "taskCode": "T13", "windowDays": 1, "instruction": "Today, tell one person — a parent, friend, or teacher — something you are proud of. Notice how it feels.", "missionType": "Share", "parentNotice": "Your child has a Proud Share mission today — give them a moment to tell you something they are proud of!", "verifyForBonus": true}'::jsonb, 25, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz),
  ('9b60c8aa-e19b-4460-9873-116059c66daa'::uuid, 'f912940f-a1db-4f73-af0b-dcffb90c6690'::uuid, 6, 'reflection'::layer_type, 'What does proud feel like?', '{"prompt": "What does proud feel like in your body? What is something you did recently that made you feel proud?", "taskCode": "T14", "inputType": "Both", "journalLabel": "My Proud Story"}'::jsonb, 10, '2026-05-05 12:11:11.174544+00'::timestamptz, '2026-05-05 12:11:11.174544+00'::timestamptz)
